var t=`1007-khao-pad`;var a=`world-1007`;var n=`TH`;var o=`southeast-asia`;var s=8;var r=88;var h={en:`Khao Pad`,ua:`Кхао пад`};var l={en:`Khao Pad is a dish from Thailand prepared with jasmine rice, garlic, shallot, chicken egg. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Кхао пад, страва кухні країни Таїланд, яку готують із таких продуктів: рис жасмин, часник, цибуля шалот, куряче яйце. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var d=[{en:`Rinse the rice, add the listed water, stock, coconut milk and aromatics as specified, cover and cook gently for about 22 minutes until tender and the liquid absorbs.`,ua:`Промийте рис, додайте зазначені воду, бульйон, кокосове молоко та прянощі, накрийте й готуйте приблизно 22 хвилин до м’якості та поглинання рідини.`,t:[`rice-washing`,`absorption-cooking`],m:22,i:[[`jasmine-rice`,370,`g`],[`water`,620,`ml`]]},{en:`Spread the just-cooked rice on a shallow tray, cool promptly and refrigerate until cold; do not leave cooked rice at room temperature.`,ua:`Розкладіть щойно зварений рис тонким шаром, швидко охолодіть і поставте в холодильник до охолодження; не залишайте готовий рис за кімнатної температури.`,t:[`rapid-chilling`],m:45,i:[]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 6 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 6 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:6,i:[[`garlic`,4,`clove`],[`shallot`,90,`g`],[`sunflower-oil`,35,`ml`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 5 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 5 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:5,i:[[`chicken-egg`,3,`pcs`],[`shrimp`,200,`g`]]},{en:`Stir-fry the already chilled rice with the soy and fish sauces over high heat, breaking up clumps, until the rice is piping hot throughout.`,ua:`Обсмажте вже охолоджений рис із соєвим і рибним соусами на сильному вогні, розбиваючи грудочки, доки він повністю не прогріється.`,t:[`chopping`,`sauteing`],m:7,i:[[`light-soy-sauce`,28,`ml`],[`fish-sauce`,23,`ml`],[`white-granulated-sugar`,8,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cucumber`,130,`g`],[`lime`,1,`pcs`],[`green-onion`,25,`g`]]}];var u={slug:t,id:a,country:`TH`,region:o,servings:8,minutes:88,title:h,text:l,steps:d};export{n as country,u as default,a as id,r as minutes,o as region,s as servings,t as slug,d as steps,l as text,h as title};